                {
                    b.Property<int>("Id")
                        .ValueGeneratedOnAdd()
                        .HasColumnType("integer")
                        .HasColumnName("id");

                    NpgsqlPropertyBuilderExtensions.UseIdentityByDefaultColumn(b.Property<int>("Id"));
                    NpgsqlPropertyBuilderExtensions.HasIdentityOptions(b.Property<int>("Id"), 1000L, null, null, null, null, null);

                    b.Property<string>("Estado")
                        .IsRequired()
                        .HasMaxLength(15)
                        .HasColumnType("character varying(15)")
                        .HasColumnName("estado");

                    b.Property<int>("EstudianteId")
                        .HasColumnType("integer")
                        .HasColumnName("estudiante_id");

                    b.Property<DateTimeOffset>("FechaInscripcion")
                        .HasColumnType("timestamp with time zone")
                        .HasColumnName("fecha_inscripcion");

                    b.Property<int>("MateriaId")
                        .HasColumnType("integer")
                        .HasColumnName("materia_id");

                    b.Property<string>("PeriodoAcademico")
                        .IsRequired()
                        .HasMaxLength(10)
                        .HasColumnType("character varying(10)")
                        .HasColumnName("periodo_academico");

                    b.HasKey("Id")
                        .HasName("pk_inscripciones");

                    b.HasIndex("MateriaId", "PeriodoAcademico")
                        .HasDatabaseName("ix_inscripciones_materia_id_periodo_academico");

                    b.HasIndex("EstudianteId", "MateriaId", "PeriodoAcademico")
                        .IsUnique()
                        .HasDatabaseName("ux_inscripciones_activa")
                        .HasFilter("estado = 'Activa'");

